from bagimlilik import kurulum_sirasi, DonguHatasi


def test_basit_zincir():
    deps = {'b': ['a'], 'c': ['b']}
    result = kurulum_sirasi(deps)
    assert result == ['a', 'b', 'c'], f'Beklenen ["a", "b", "c"], alindi: {result}'
    print('Test 1 (basit zincir): PASSED')


def test_ayni_bagimlilik():
    deps = {'b': ['a'], 'c': ['a']}
    result = kurulum_sirasi(deps)
    assert result == ['a', 'b', 'c'] or result == ['a', 'c', 'b'], f'Beklenen ["a", "b", "c"] veya ["a", "c", "b"], alindi: {result}'
    print('Test 2 (aynı bağımlılık): PASSED')


def test_dongu():
    deps = {'a': ['b'], 'b': ['c'], 'c': ['a']}
    try:
        kurulum_sirasi(deps)
        assert False, "DonguHatasi fırlatılmadı!"
    except DonguHatasi as e:
        assert 'a' in e.dongu and 'b' in e.dongu and 'c' in e.dongu, f'Döngüde tüm paketler olmalı: {e.dongu}'
        print('Test 3 (döngü): PASSED')


def test_kendine_bagimli():
    deps = {'a': ['a']}
    try:
        kurulum_sirasi(deps)
        assert False, "DonguHatasi fırlatılmadı!"
    except DonguHatasi as e:
        assert e.dongu == ['a'], f'Beklenen ["a"], alindi: {e.dongu}'
        print('Test 4 (kendine bağımlı): PASSED')


def test_tek_paket():
    deps = {'a': []}
    result = kurulum_sirasi(deps)
    assert result == ['a'], f'Beklenen ["a"], alindi: {result}'
    print('Test 5 (tek paket): PASSED')


def test_bos_bagimlilik():
    deps = {}
    result = kurulum_sirasi(deps)
    assert result == [], f'Beklenen [], alindi: {result}'
    print('Test 6 (boş): PASSED')


def test_tekrar_eden_bagimliklar():
    deps = {'b': ['a', 'a'], 'c': ['b']}
    result = kurulum_sirasi(deps)
    assert result == ['a', 'b', 'c'], f'Beklenen ["a", "b", "c"], alindi: {result}'
    print('Test 7 (tekrar eden): PASSED')


def test_alfabetik_siralama():
    deps = {'d': ['a'], 'e': ['a']}
    result = kurulum_sirasi(deps)
    assert result[0] == 'a', f'İlk paket "a" olmalı, alindi: {result}'
    print('Test 8 (alfabetik): PASSED')


def test_karma_dongu():
    deps = {'a': ['b'], 'b': ['c'], 'c': ['d'], 'd': ['a']}
    try:
        kurulum_sirasi(deps)
        assert False, "DonguHatasi fırlatılmadı!"
    except DonguHatasi as e:
        assert set(e.dongu) == {'a', 'b', 'c', 'd'}, f'Döngüde tüm paketler olmalı: {e.dongu}'
        # Döngü alfabetik olarak en küçükten başlamalı
        assert e.dongu[0] == min(e.dongu), f"Döngü en küçük elemandan başlamalı: {e.dongu}"
        print('Test 9 (karma döngü): PASSED')


def test_kesikli_bagimliklar():
    deps = {'a': [], 'b': ['c'], 'c': []}
    result = kurulum_sirasi(deps)
    # a ve c bağımlılığı yok, b'ye bağımlı
    assert result[0] == 'a', f"İlk paket \"a\" olmalı (alfabetik), alindi: {result}"
    print('Test 10 (kesikli bağımlılıklar): PASSED')


def test_buyuk_dongu():
    # Büyük bir döngü oluştur
    deps = {}
    for i in range(5, 0, -1):
        deps[f'p{i}'] = [f'p{i-1}'] if i > 1 else ['p5']

    try:
        kurulum_sirasi(deps)
        assert False, "DonguHatasi fırlatılmadı!"
    except DonguHatasi as e:
        assert set(e.dongu) == {'p1', 'p2', 'p3', 'p4', 'p5'}, f'Döngüde tüm paketler olmalı: {e.dongu}'
        print('Test 11 (büyük döngü): PASSED')


def test_coklu_dongu():
    # Birden fazla bağımsız döngü
    deps = {'a': ['b'], 'b': ['a'], 'c': ['d'], 'd': ['c']}
    try:
        kurulum_sirasi(deps)
        assert False, "DonguHatasi fırlatılmadı!"
    except DonguHatasi as e:
        # Hangi döngü bulunduğunu kontrol et
        if set(e.dongu) == {'a', 'b'} or set(e.dongu) == {'c', 'd'}:
            print('Test 12 (çoklu döngü): PASSED')
        else:
            assert False, f'Beklenen döngüler {{a,b}} veya {{c,d}}, alindi: {e.dongu}'


if __name__ == '__main__':
    test_basit_zincir()
    test_ayni_bagimlilik()
    test_dongu()
    test_kendine_bagimli()
    test_tek_paket()
    test_bos_bagimlilik()
    test_tekrar_eden_bagimliklar()
    test_alfabetik_siralama()
    test_karma_dongu()
    test_kesikli_bagimliklar()
    test_buyuk_dongu()
    test_coklu_dongu()
    print('Tüm testler geçti!')

